"""Regenerate the minimal chat snapshot's manifest after contract changes.

Run ``python -m tests.fixtures.chat._generate`` from the project root.
The public fixture data, historical fixture identity and covered contract set
remain fixed. Intentional negative publication fixtures live separately under
``tests/fixtures/site`` and are regenerated by their own generator.
"""

from __future__ import annotations

from pathlib import Path

from src.publish import manifest as manifest_mod

SITE = Path(__file__).resolve().parent / "site"


def main() -> None:
    original = manifest_mod.load_manifest(SITE)
    before = manifest_mod.file_entries(SITE)
    current_contracts = manifest_mod.contract_hashes()
    manifest = manifest_mod.build_manifest(
        SITE,
        original["analysis_manifest"],
        code_commit=original["code_commit"],
        generated_at=original["generated_at"],
        contracts={name: current_contracts[name] for name in original["contracts"]},
    )
    manifest_mod.write_manifest(SITE, manifest)
    if manifest_mod.file_entries(SITE) != before:
        raise AssertionError("manifest regeneration changed the public chat fixture data")
    print(f"refreshed current contract hashes under {SITE}")


if __name__ == "__main__":
    main()
